/*
 * Taproot base stylesheet: optional page defaults.
 *
 * The components style only themselves. This file styles the page around them: the base font,
 * text color, and background, and a type recipe for each heading level. It is the web form of
 * guideline.page-setup in @taproot-ds/spec.
 *
 * Load it after tokens.css:
 *
 *   import "@taproot-ds/tokens/css";
 *   import "@taproot-ds/tokens/base";
 *
 * Every selector is wrapped in :where(), so product styles override it without raising
 * specificity. It sets no margins, resets, or layout.
 */

:where(html) {
  background-color: var(--ds-semantic-color-background-default);
  color: var(--ds-semantic-color-foreground-default);
  -webkit-text-size-adjust: 100%;
  text-size-adjust: 100%;
}

:where(body) {
  font-family: var(--ds-semantic-typography-body-md-font-family);
  font-size: var(--ds-semantic-typography-body-md-font-size);
  font-weight: var(--ds-semantic-typography-body-md-font-weight);
  line-height: var(--ds-semantic-typography-body-md-line-height);
  letter-spacing: var(--ds-semantic-typography-body-md-letter-spacing);
  background-color: var(--ds-semantic-color-background-default);
  color: var(--ds-semantic-color-foreground-default);
}

