  font-size: var(--ds-semantic-typography-heading-lg-font-size);
  font-weight: var(--ds-semantic-typography-heading-lg-font-weight);
  line-height: var(--ds-semantic-typography-heading-lg-line-height);
  letter-spacing: var(--ds-semantic-typography-heading-lg-letter-spacing);
}

:where(h2) {
