  "content": "<!doctype html>
<html lang="en">
  <head>
    <meta charset="utf-8" />
    <meta name="viewport" content="width=device-width, initial-scale=1" />
    <title>Address</title>
    <link rel="preconnect" href="https://fonts.googleapis.com" />
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
    <link
      rel="stylesheet"
      href="https://fonts.googleapis.com/css2?family=Lora:ital,wght@0,400..700;1,400..700&family=Source+Sans+3:wght@300..900&family=JetBrains+Mono:wght@400;500;600&display=swap"
    />
    <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/tokens.css" />
    <link rel="stylesheet" href="./node_modules/@taproot-ds/tokens/dist/css/base.css" />
    <style>
      body {
        margin: 0;
      }
      main {
        max-inline-size: 32rem;
        margin-inline: auto;
        padding: var(--ds-primitives-space-8) var(--ds-primitives-space-4);
      }
      h1 {
        margin: 0 0 var(--ds-primitives-space-6);
      }
      form {
        display: flex;
        flex-direction: column;
        gap: var(--ds-primitives-space-5);
      }
      .actions {
        margin-block-start: var(--ds-primitives-space-2);
      }
      #status {
        margin: 0;
        color: var(--ds-semantic-color-foreground-muted);
      }
    </style>
    <script type="module">
      import { defineTextArea } from "./node_modules/@taproot-ds/web-components/src/text-area.js";
      import { defineSelect } from "./node_modules/@taproot-ds/web-components/src/select.js";
      import { defineTextField } from "./node_modules/@taproot-ds/web-components/src/text-field.js";
      import { defineButton } from "./node_modules/@taproot-ds/web-components/src/button.js";

      defineTextArea();
      defineSelect();
      defineTextField();
      defineButton();

      const form = document.getElementById("address-form");
      const postal = document.getElementById("postal-code");
      const status = document.getElementById("status");

      postal.addEventListener("input", () => postal.removeAttribute("error"));
      form.addEventListener("reset", () => postal.removeAttribute("error"));

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";
        if (!postal.value || !postal.value.trim()) {
          postal.setAttribute("error", "Enter a postal code");
          postal.focus();
          return;
        }
        status.textContent = "Address saved.";
      });
    </script>
  </head>
  <body>
    <main>
      <h1>Address</h1>
      <form id="address-form" novalidate>
        <ds-text-area
          label="Street address"
          name="street-address"
          autocomplete="street-address"
          rows="3"
          hint="Put the building, street, and any apartment or suite on separate lines."
        ></ds-text-area>

        <ds-select label="Country" name="country">
          <option value="">Choose a country</option>
          <option value="AU">Australia</option>
          <option value="BR">Brazil</option>
          <option value="CA">Canada</option>
          <option value="DE">Germany</option>
          <option value="US">United States</option>
        </ds-select>

        <ds-text-field
          id="postal-code"
          label="Postal code"
          name="postal-code"
          autocomplete="postal-code"
          required
        ></ds-text-field>

        <div class="actions">
          <ds-button type="submit" variant="primary">Save address</ds-button>
        </div>
        <p id="status" role="status"></p>
      </form>
    </main>
  </body>
</html>
